import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Lingma cookbook","description":"After Lingma / Qoder CN is installed: pick a chat mode, write a structured task, let Agent run the terminal, and attach MCP.","frontmatter":{"title":"Lingma cookbook","description":"After Lingma / Qoder CN is installed: pick a chat mode, write a structured task, let Agent run the terminal, and attach MCP.","domain":"product","tags":["coding-agent"],"role":"cookbook"},"headers":[],"relativePath":"products/lingma/lingma-cookbook.md","filePath":"products/lingma/lingma-cookbook.md","lastUpdated":1787107158000}'),r={name:"products/lingma/lingma-cookbook.md"};function i(s,t,l,d,h,p){return n(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="lingma-cookbook" tabindex="-1">Lingma cookbook <a class="header-anchor" href="#lingma-cookbook" aria-label="Permalink to &quot;Lingma cookbook&quot;">​</a></h1><p>For readers who can already sign in and accept a completion. Install is in the <a href="./lingma.html">tutorial</a>. Keys are in the <a href="./lingma-cheatsheet.html">cheatsheet</a>.</p><h2 id="pick-the-chat-mode" tabindex="-1">Pick the chat mode <a class="header-anchor" href="#pick-the-chat-mode" aria-label="Permalink to &quot;Pick the chat mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Job</th><th>Mode</th><th>Official reason</th></tr></thead><tbody><tr><td>Explain this React component</td><td><strong>Ask</strong></td><td>&quot;Does not edit project files&quot;</td></tr><tr><td>Change a named set of files and review the diff</td><td><strong>Edit</strong></td><td>Precise, faster than Agent</td></tr><tr><td>Add a feature: edit + install + test</td><td><strong>Agent</strong></td><td>Can plan, use the terminal, call MCP</td></tr><tr><td>Multi-file edits in Lingma IDE / JetBrains</td><td><strong>Agent</strong> (there is no Edit)</td><td>Official: those clients do not support Edit</td></tr><tr><td>Visual Studio</td><td><strong>Ask</strong></td><td>Official: Ask-only for now</td></tr></tbody></table><p>If you can spot a wrong edit at a glance, use Agent. Otherwise start in Ask.</p><p>Sources: <a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">Chat overview</a>, <a href="https://help.aliyun.com/zh/lingma/edit" target="_blank" rel="noreferrer">Edit</a>, <a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">Agent</a>.</p><h2 id="write-the-task-the-way-the-docs-ask" tabindex="-1">Write the task the way the docs ask <a class="header-anchor" href="#write-the-task-the-way-the-docs-ask" aria-label="Permalink to &quot;Write the task the way the docs ask&quot;">​</a></h2><p>Official text (<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">Chat overview</a>):</p><blockquote><p>结构化地描述需求：首先需要澄清我们需要通义灵码帮我们做什么，建议包含一个明确的目标，并通过步骤式的结构化描述，详细地描述您期望完成的编码任务和要求。</p><p>给出相关的上下文：可以选择代码文件、图片、codebase、codeChanges 等上下文。</p><p>明确生成要求：告诉通义灵码您期望它遵循的要求，比如语言、规范、格式、变更目标等，如“生成变更时，同时为每个方法生成英文注释”。</p><p>多多互动，逐步迭代。</p></blockquote><p>Template (structure from those four bullets):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: add lastActiveAt sorting to src/components/UserTable.tsx.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Steps:</span></span>
<span class="line"><span>1. Change the existing component only</span></span>
<span class="line"><span>2. Default descending; click the header to toggle</span></span>
<span class="line"><span>3. Add TypeScript types; no any</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>- Add English comments for every method you change</span></span>
<span class="line"><span>- Do not touch the API layer</span></span></code></pre></div><p>Then attach files / images / codebase. Lingma IDE context <strong>does not support the knowledge base</strong> yet (same official page).</p><p>Agent mode can expand a draft prompt via the optimize-input control (<a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">Agent</a>). Read the expanded prompt before you send it.</p><h2 id="run-an-agent-task-that-has-side-effects" tabindex="-1">Run an Agent task that has side effects <a class="header-anchor" href="#run-an-agent-task-that-has-side-effects" aria-label="Permalink to &quot;Run an Agent task that has side effects&quot;">​</a></h2><ol><li>Switch to <strong>Agent</strong>.</li><li>State the goal and the hard boundary.</li><li>For a complex task, wait for a plan or send <code>/plan</code>.</li><li>When a terminal command appears, click <strong>Run</strong> only if you understand it.</li><li>Accept or reject each file in the diff.</li></ol><p>Official auto-run allowlist (<a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">Agent</a>):</p><blockquote><p>具体配置路径为插件 <strong>Chat</strong> 设置页面的 <strong>Auto-Run</strong> 区域，在 <strong>Terminal in Agent Mode</strong> 下方的输入框中添加允许自动运行的命令。如需添加多个命令，可以使用英文逗号分隔。</p></blockquote><p>Do not put <code>rm</code>, <code>git push</code>, or <code>npm publish</code> on that list in week one.</p><p>If Agent cannot start a terminal in VS Code, read <a href="https://help.aliyun.com/zh/lingma/description-of-terminal-execution-exception" target="_blank" rel="noreferrer">Terminal exceptions</a>: the VS Code plugin needs the Shell Integration API, <strong>VS Code &gt; 1.93</strong>, and a supported default shell. That is a different floor from the 1.68.0 install requirement.</p><h2 id="attach-mcp" tabindex="-1">Attach MCP <a class="header-anchor" href="#attach-mcp" aria-label="Permalink to &quot;Attach MCP&quot;">​</a></h2><p>Official boundary (<a href="https://help.aliyun.com/zh/lingma/guide-for-using-mcp" target="_blank" rel="noreferrer">MCP guide</a>):</p><blockquote><p>MCP（Model Context Protocol）是一种开放标准协议，使其智能体的能力和场景得到拓展。</p><p>Markets: <a href="https://www.modelscope.cn/mcp" target="_blank" rel="noreferrer">ModelScope MCP</a>, <a href="https://mcp.higress.ai/" target="_blank" rel="noreferrer">Higress MCP</a>.</p><p>Example jobs: database schemas / DAO, online docs, design-to-code.</p></blockquote><p>Official path into the MCP page in IntelliJ (<a href="https://help.aliyun.com/zh/lingma/use-lingma-mastergo-mcp-to-transforming-mastergo-design-draft-into-front-end-code" target="_blank" rel="noreferrer">MasterGo recipe</a>):</p><ol><li>Open <strong>chat</strong> from the sidebar icon.</li><li>Open <strong>MCP</strong>: the <strong>MCP tools</strong> link on the welcome line, or avatar → <strong>Personal settings</strong> → <strong>MCP</strong>.</li><li>Switch to <strong>Agent</strong>, then write the prompt.</li><li>Confirm each MCP call. The result becomes later context.</li></ol><p>Do not paste third-party JSON from blog posts as if it were official config. Copy only what the <a href="https://help.aliyun.com/zh/lingma/guide-for-using-mcp" target="_blank" rel="noreferrer">MCP guide</a> shows.</p><h2 id="turn-on-next-edit-suggestion-nes" tabindex="-1">Turn on Next Edit Suggestion (NES) <a class="header-anchor" href="#turn-on-next-edit-suggestion-nes" aria-label="Permalink to &quot;Turn on Next Edit Suggestion (NES)&quot;">​</a></h2><p>Official definition (<a href="https://help.aliyun.com/zh/lingma/next-edit-suggestion" target="_blank" rel="noreferrer">NES</a>): predict the next change from full-file context, recent edits, and the caret. <strong>Tab</strong> accepts, <strong>Esc</strong> rejects.</p><p>Same page: open personal settings with <code>⌘ ⇧ ,</code> (macOS) or <code>Ctrl Shift ,</code> (Windows) and enable <strong>NES</strong>. <strong>Qoder CN IDE only supports Auto mode.</strong></p><p>IDE changelogs later rename NES to <strong>NEXT</strong>. Trust the label in your installed client.</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th><th>Source</th></tr></thead><tbody><tr><td>Marketplace search misses the plugin</td><td>Old page says TONGYI Lingma; Help Center says Qoder CN</td><td><a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">Download</a>, <a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">Install</a></td></tr><tr><td>No VS Code sidebar icon</td><td>Right-click the activity bar, enable Qoder CN</td><td><a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">Install</a></td></tr><tr><td>No Edit mode in JetBrains / Lingma IDE</td><td>Use Agent</td><td><a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">Chat overview</a></td></tr><tr><td>Agent cannot run the terminal in VS Code</td><td>VS Code &gt; 1.93 + supported shell integration</td><td><a href="https://help.aliyun.com/zh/lingma/description-of-terminal-execution-exception" target="_blank" rel="noreferrer">Terminal exceptions</a></td></tr><tr><td>Old Lingma IDE missing new features</td><td>Uninstall Lingma IDE, install Qoder CN IDE</td><td><a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">Billing</a></td></tr><tr><td>Using it as Qwen chat</td><td>Wrong product. See the <a href="./">map</a></td><td><a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a></td></tr></tbody></table>`,31)])])}const k=e(r,[["render",i]]);export{u as __pageData,k as default};
